async function ambilMenu(id) {
  const key = `menu:${id}`;
  const simpanan = await client.get(key);
  if (simpanan) return JSON.parse(simpanan);
  const menu = await dbAmbilMenu(id);
  if (menu) await client.set(key, JSON.stringify(menu), { EX: 120 });
  return menu;
}

async function ubahHarga(id, harga) {
  await dbUbahHarga(id, harga);
  await client.del(`menu:${id}`);
}

async function batasPesanan(nis) {
  const key = `batas:${nis}`;
  const jumlah = await client.incr(key);
  if (jumlah === 1) await client.expire(key, 60);
  return jumlah <= 3;
}

async function tambahPoin(nis, poin) {
  return await client.zIncrBy("poin", poin, nis);
}

async function papanPeringkat(n) {
  const daftar = await client.zRangeWithScores("poin", 0, n - 1, { REV: true });
  return daftar.map((x) => ({ nis: x.value, poin: x.score }));
}

async function antrePesanan(pesanan) {
  return await client.rPush("antrean", JSON.stringify(pesanan));
}

async function ambilPesanan() {
  const isi = await client.lPop("antrean");
  return isi ? JSON.parse(isi) : null;
}

async function buatSesi(token, nis) {
  const key = `sesi:${token}`;
  await client.hSet(key, { nis });
  await client.expire(key, 1800);
}

async function cekSesi(token) {
  const key = `sesi:${token}`;
  const nis = await client.hGet(key, "nis");
  if (!nis) return null;
  await client.expire(key, 1800);
  return nis;
}

