const KEY = "kantin:pengumuman";

async function bacaPengumuman() {
  const isi = await client.get(KEY);
  return isi ?? "Belum ada pengumuman";
}

async function simpanPengumuman(teks) {
  await client.set(KEY, teks);
}

async function adaPengumuman() {
  return (await client.exists(KEY)) === 1;
}

async function hapusPengumuman() {
  return await client.del(KEY);
}

