// mini-redis: in-memory Redis look-alike for exercises (node-redis style, camelCase). Paste into `setup`.
// const client = buatClient();  await client.set("k", "v", { EX: 60 }); client.jam.maju(61) moves the fake clock.
// Values are strings like real Redis (numbers are stored as text). Results are plain values; `await` still works.
function buatClient() {
  const data = new Map(); // key -> { type, v, exp }
  const jam = { t: 0, maju(detik) { this.t += detik * 1000; } };
  const live = (k) => { const e = data.get(k); if (e && e.exp != null && e.exp <= jam.t) { data.delete(k); return undefined; } return e; };
  const ofType = (k, type, init) => {
    const e = live(k);
    if (!e) { if (!init) return undefined; const n = { type, v: init(), exp: null }; data.set(k, n); return n; }
    if (e.type !== type) throw new Error("WRONGTYPE Operation against a key holding the wrong kind of value");
    return e;
  };
  const str = (x) => String(x);
  const glob = (p) => new RegExp("^" + p.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*").replace(/\?/g, ".") + "$");
  const toNum = (v) => { const n = Number(v); if (!Number.isInteger(n)) throw new Error("ERR value is not an integer or out of range"); return n; };
  const subs = new Map();
  const c = {
    jam,
    async connect() { return c; }, async close() { c.isOpen = false; }, destroy() { c.isOpen = false; }, async quit() { return "OK"; }, isOpen: true,
    // keys
    set(k, v, opt = {}) {
      if (opt.NX && live(k)) return null;
      if (opt.XX && !live(k)) return null;
      const old = live(k);
      data.set(k, { type: "string", v: str(v), exp: opt.EX ? jam.t + opt.EX * 1000 : opt.PX ? jam.t + opt.PX : opt.KEEPTTL && old ? old.exp : null });
      return "OK";
    },
    get(k) { const e = ofType(k, "string"); return e ? e.v : null; },
    mGet(ks) { return ks.map((k) => c.get(k)); },
    del(ks) { return [].concat(ks).filter((k) => live(k) && data.delete(k)).length; },
    exists(ks) { return [].concat(ks).filter((k) => live(k)).length; },
    expire(k, s, mode) { const e = live(k); if (!e) return 0; const t = jam.t + s * 1000; if ((mode === "NX" && e.exp != null) || (mode === "XX" && e.exp == null) || (mode === "GT" && (e.exp == null || t <= e.exp)) || (mode === "LT" && e.exp != null && t >= e.exp)) return 0; e.exp = t; return 1; },
    persist(k) { const e = live(k); if (!e || e.exp == null) return 0; e.exp = null; return 1; },
    ttl(k) { const e = live(k); if (!e) return -2; if (e.exp == null) return -1; return Math.ceil((e.exp - jam.t) / 1000); },
    type(k) { const e = live(k); return e ? e.type : "none"; },
    keys(p = "*") { const r = glob(p); return [...data.keys()].filter((k) => live(k) && r.test(k)).sort(); },
    flushAll() { data.clear(); return "OK"; },
    incr(k) { return c.incrBy(k, 1); },
    decr(k) { return c.incrBy(k, -1); },
    decrBy(k, n) { return c.incrBy(k, -n); },
    incrBy(k, n) { const e = ofType(k, "string", () => "0"); e.v = str(toNum(e.v) + n); return Number(e.v); },
    append(k, s) { const e = ofType(k, "string", () => ""); e.v += s; return e.v.length; },
    // hashes
    hSet(k, f, v) { const e = ofType(k, "hash", () => new Map()); const obj = typeof f === "object" ? f : { [f]: v }; let n = 0; for (const [a, b] of Object.entries(obj)) { if (!e.v.has(a)) n++; e.v.set(a, str(b)); } return n; },
    hGet(k, f) { const e = ofType(k, "hash"); return e?.v.get(f) ?? null; },
    hGetAll(k) { const e = ofType(k, "hash"); return e ? Object.fromEntries(e.v) : {}; },
    hDel(k, fs) { const e = ofType(k, "hash"); return e ? [].concat(fs).filter((f) => e.v.delete(f)).length : 0; },
    hExists(k, f) { return ofType(k, "hash")?.v.has(f) ? 1 : 0; },
    hIncrBy(k, f, n) { const e = ofType(k, "hash", () => new Map()); const v = toNum(e.v.get(f) ?? "0") + n; e.v.set(f, str(v)); return v; },
    hLen(k) { return ofType(k, "hash")?.v.size ?? 0; },
    // lists
    lPush(k, vs) { const e = ofType(k, "list", () => []); for (const v of [].concat(vs)) e.v.unshift(str(v)); return e.v.length; },
    rPush(k, vs) { const e = ofType(k, "list", () => []); for (const v of [].concat(vs)) e.v.push(str(v)); return e.v.length; },
    lPop(k) { const e = ofType(k, "list"); const v = e?.v.shift() ?? null; if (e && !e.v.length) data.delete(k); return v; },
    rPop(k) { const e = ofType(k, "list"); const v = e?.v.pop() ?? null; if (e && !e.v.length) data.delete(k); return v; },
    lLen(k) { return ofType(k, "list")?.v.length ?? 0; },
    lRange(k, a, b) { const l = ofType(k, "list")?.v ?? []; const n = l.length; const s = a < 0 ? Math.max(n + a, 0) : a; const e = b < 0 ? n + b : Math.min(b, n - 1); return s > e ? [] : l.slice(s, e + 1); },
    lTrim(k, a, b) { const e = ofType(k, "list"); if (e) e.v = c.lRange(k, a, b); return "OK"; },
    // sets
    sAdd(k, ms) { const e = ofType(k, "set", () => new Set()); let n = 0; for (const m of [].concat(ms)) if (!e.v.has(str(m))) { e.v.add(str(m)); n++; } return n; },
    sRem(k, ms) { const e = ofType(k, "set"); return e ? [].concat(ms).filter((m) => e.v.delete(str(m))).length : 0; },
    sMembers(k) { return [...(ofType(k, "set")?.v ?? [])].sort(); },
    sIsMember(k, m) { return ofType(k, "set")?.v.has(str(m)) ? 1 : 0; },
    sCard(k) { return ofType(k, "set")?.v.size ?? 0; },
    sInter(ks) { const [a, ...r] = ks.map((k) => ofType(k, "set")?.v ?? new Set()); return [...a].filter((m) => r.every((s) => s.has(m))).sort(); },
    sUnion(ks) { return [...new Set(ks.flatMap((k) => [...(ofType(k, "set")?.v ?? [])]))].sort(); },
    // sorted sets: members as { score, value }
    zAdd(k, ms) { const e = ofType(k, "zset", () => new Map()); let n = 0; for (const { score, value } of [].concat(ms)) { if (!e.v.has(str(value))) n++; e.v.set(str(value), Number(score)); } return n; },
    zIncrBy(k, by, m) { const e = ofType(k, "zset", () => new Map()); const v = (e.v.get(str(m)) ?? 0) + by; e.v.set(str(m), v); return v; },
    zScore(k, m) { const v = ofType(k, "zset")?.v.get(str(m)); return v ?? null; },
    zCard(k) { return ofType(k, "zset")?.v.size ?? 0; },
    _sorted(k, rev) { const l = [...(ofType(k, "zset")?.v ?? new Map())].map(([value, score]) => ({ value, score })); l.sort((x, y) => x.score - y.score || (x.value < y.value ? -1 : x.value > y.value ? 1 : 0)); return rev ? l.reverse() : l; },
    _slice(l, a, b) { const n = l.length; const s = a < 0 ? Math.max(n + a, 0) : a; const e = b < 0 ? n + b : Math.min(b, n - 1); return s > e ? [] : l.slice(s, e + 1); },
    zRange(k, a, b, opt = {}) { return c._slice(c._sorted(k, opt.REV), a, b).map((x) => x.value); },
    zRangeWithScores(k, a, b, opt = {}) { return c._slice(c._sorted(k, opt.REV), a, b); },
    zRank(k, m) { const i = c._sorted(k).findIndex((x) => x.value === str(m)); return i < 0 ? null : i; },
    zRevRank(k, m) { const i = c._sorted(k, true).findIndex((x) => x.value === str(m)); return i < 0 ? null : i; },
    zRem(k, ms) { const e = ofType(k, "zset"); return e ? [].concat(ms).filter((m) => e.v.delete(str(m))).length : 0; },
    // transactions: commands queue until exec()
    multi() {
      const q = [];
      const t = new Proxy({}, { get: (_, name) => (name === "exec" ? () => q.map(([n, a]) => c[n](...a)) : (...a) => (q.push([name, a]), t)) });
      return t;
    },
    // pub/sub (synchronous delivery)
    subscribe(ch, fn) { if (!subs.has(ch)) subs.set(ch, []); subs.get(ch).push(fn); },
    publish(ch, msg) { const l = subs.get(ch) ?? []; l.forEach((fn) => fn(str(msg), ch)); return l.length; },
  };
  return c;
}

