async function ambilKeranjang(nis) {
  const teks = await client.get(`keranjang:${nis}`);
  return teks ? JSON.parse(teks) : [];
}

async function totalBelanja(nis) {
  const isi = await ambilKeranjang(nis);
  return isi.reduce((t, x) => t + x.harga * x.jumlah, 0);
}

async function simpanKeranjang(nis, isi) {
  await client.set(`keranjang:${nis}`, JSON.stringify(isi), { EX: 3600 });
}

async function ambilMenu(id) {
  const h = await client.hGetAll(`menu:${id}`);
  if (Object.keys(h).length === 0) return null;
  return { nama: h.nama, harga: Number(h.harga), stok: Number(h.stok) };
}

