    del(ks) { return [].concat(ks).filter((k) => live(k) && data.delete(k)).length; },
    exists(ks) { return [].concat(ks).filter((k) => live(k)).length; },
    expire(k, s, mode) { const e = live(k); if (!e) return 0; const t = jam.t + s * 1000; if ((mode === "NX" && e.exp != null) || (mode === "XX" && e.exp == null) || (mode === "GT" && (e.exp == null || t <= e.exp)) || (mode === "LT" && e.exp != null && t >= e.exp)) return 0; e.exp = t; return 1; },
    persist(k) { const e = live(k); if (!e || e.exp == null) return 0; e.exp = null; return 1; },
    ttl(k) { const e = live(k); if (!e) return -2; if (e.exp == null) return -1; return Math.ceil((e.exp - jam.t) / 1000); },
    type(k) { const e = live(k); return e ? e.type : "none"; },
    keys(p = "*") { const r = glob(p); return [...data.keys()].filter((k) => live(k) && r.test(k)).sort(); },
    flushAll() { data.clear(); return "OK"; },
    incr(k) { return c.incrBy(k, 1); },
    decr(k) { return c.incrBy(k, -1); },
    decrBy(k, n) { return c.incrBy(k, -n); },
    incrBy(k, n) { const e = ofType(k, "string", () => "0"); e.v = str(toNum(e.v) + n); return Number(e.v); },
    append(k, s) { const e = ofType(k, "string", () => ""); e.v += s; return e.v.length; },
    // hashes
    hSet(k, f, v) { const e = ofType(k, "hash", () => new Map()); const obj = typeof f === "object" ? f : { [f]: v }; let n = 0; for (const [a, b] of Object.entries(obj)) { if (!e.v.has(a)) n++; e.v.set(a, str(b)); } return n; },
    hGet(k, f) { const e = ofType(k, "hash"); return e?.v.get(f) ?? null; },
    hGetAll(k) { const e = ofType(k, "hash"); return e ? Object.fromEntries(e.v) : {}; },
    hDel(k, fs) { const e = ofType(k, "hash"); return e ? [].concat(fs).filter((f) => e.v.delete(f)).length : 0; },
    hExists(k, f) { return ofType(k, "hash")?.v.has(f) ? 1 : 0; },
    hIncrBy(k, f, n) { const e = ofType(k, "hash", () => new Map()); const v = toNum(e.v.get(f) ?? "0") + n; e.v.set(f, str(v)); return v; },
    hLen(k) { return ofType(k, "hash")?.v.size ?? 0; },
    // lists
    lPush(k, vs) { const e = ofType(k, "list", () => []); for (const v of [].concat(vs)) e.v.unshift(str(v)); return e.v.length; },
    rPush(k, vs) { const e = ofType(k, "list", () => []); for (const v of [].concat(vs)) e.v.push(str(v)); return e.v.length; },
    lPop(k) { const e = ofType(k, "list"); const v = e?.v.shift() ?? null; if (e && !e.v.length) data.delete(k); return v; },
    rPop(k) { const e = ofType(k, "list"); const v = e?.v.pop() ?? null; if (e && !e.v.length) data.delete(k); return v; },
    lLen(k) { return ofType(k, "list")?.v.length ?? 0; },
