solution.code:
async function keyTanpaTtl(pola) {
  const semua = await client.keys(pola);
  const hasil = [];
  for (const k of semua) {
    if ((await client.ttl(k)) === -1) hasil.push(k);
  }
  return hasil.sort();
}

async function pasangTtlDefault(pola, detik) {
  const daftar = await keyTanpaTtl(pola);
  for (const k of daftar) await client.expire(k, detik);
  return daftar.length;
}

